/** AUTO-GENERATED by packages/fakewiki/scripts/generate-schema.ts — do not edit. */
export const llmsReferenceBodyHtml: string = "<h1>fakewiki API reference</h1>\n<p>This file lists <code>FakeWiki</code> instance methods and Vue composables exported from the <code>fakewiki</code> package. Regenerate with <code>npm run generate</code> from the repository root or from <code>packages/fakewiki</code>.</p>\n<ul>\n<li>FakeWiki playground: <a href=\"https://todepond.github.io/FakeMediaWiki/Fullscreen/ApiPlayground\">https://todepond.github.io/FakeMediaWiki/Fullscreen/ApiPlayground</a></li>\n<li>Repository: <a href=\"https://github.com/todepond/FakeMediaWiki\">https://github.com/todepond/FakeMediaWiki</a></li>\n<li>Package: <a href=\"https://www.npmjs.com/package/fakewiki\">https://www.npmjs.com/package/fakewiki</a></li>\n</ul>\n<h2 id=\"pages-and-content\" tabindex=\"-1\">Pages and content</h2>\n<h3 id=\"getannouncements\" tabindex=\"-1\"><code>getAnnouncements</code></h3>\n<p>Get current announcements</p>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const announcements = await wiki.getAnnouncements()\n</code></pre>\n<h3 id=\"getfeaturedpage\" tabindex=\"-1\"><code>getFeaturedPage</code></h3>\n<p>Get featured page for a specific date</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>date</code> - Date object or YYYY/MM/DD string (leave blank for today’s featured page)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const featured = await wiki.getFeaturedPage()\n</code></pre>\n<h3 id=\"getonthisday\" tabindex=\"-1\"><code>getOnThisDay</code></h3>\n<p>Get “On This Day” content for a given type</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>type</code> - Type: ‘events’, ‘births’, ‘deaths’, ‘holidays’, ‘selected’</li>\n<li><code>date</code> - Date object or MM/DD string</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const onThisDay = await wiki.getOnThisDay()\n</code></pre>\n<h3 id=\"getpage\" tabindex=\"-1\"><code>getPage</code></h3>\n<p>Get full page metadata and latest revision</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const page = await wiki.getPage(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagecategories\" tabindex=\"-1\"><code>getPageCategories</code></h3>\n<p>Get page categories</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const categories = await wiki.getPageCategories(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagehero\" tabindex=\"-1\"><code>getPageHero</code></h3>\n<p>Get page hero image: thumbnail if present, otherwise the first media image.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const hero = await wiki.getPageHero(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagehistory\" tabindex=\"-1\"><code>getPageHistory</code></h3>\n<p>Get page revision history<br>\nUses caching to avoid fetching the same data twice.<br>\nUses older_than/newer_than cursors for pagination and filtering.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>options</code> - Options</li>\n<li><code>options.older_than</code> - Revision ID or timestamp - for explicit pagination</li>\n<li><code>options.newer_than</code> - Revision ID or timestamp - for explicit pagination</li>\n<li><code>options.limit</code> - Maximum results to return (default and max: PAGE_HISTORY_REVISIONS_PER_REQUEST)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const history = await wiki.getPageHistory(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagehtml\" tabindex=\"-1\"><code>getPageHtml</code></h3>\n<p>Get page content as HTML</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const html = await wiki.getPageHtml(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagemedia\" tabindex=\"-1\"><code>getPageMedia</code></h3>\n<p>Get page media (images, audio, etc.)</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const media = await wiki.getPageMedia(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagemobilehtml\" tabindex=\"-1\"><code>getPageMobileHtml</code></h3>\n<p>Get page mobile-optimized HTML</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const html = await wiki.getPageMobileHtml(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagesbacklinks\" tabindex=\"-1\"><code>getPagesBacklinks</code></h3>\n<p>Get pages that link to the given page(s) (backlinks / “What links here”)<br>\nUses MediaWiki Action API prop=linkshere.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code> - Array of page titles to find backlinks for</li>\n<li><code>options</code> - Options</li>\n<li><code>options.namespace</code> - Filter by namespace (e.g., 0 for main namespace)</li>\n<li><code>options.limit</code> - Max backlinks per page (default 500)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const backlinks = await wiki.getPagesBacklinks([&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;])\n</code></pre>\n<h3 id=\"getpageslinks\" tabindex=\"-1\"><code>getPagesLinks</code></h3>\n<p>Get outgoing wikilinks for multiple pages (intra-language links)<br>\nAutomatically handles pagination to fetch all links.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code> - Array of page titles</li>\n<li><code>options</code> - Options</li>\n<li><code>options.namespace</code> - Filter by namespace (e.g., 0 for main namespace)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const links = await wiki.getPagesLinks([&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;])\n</code></pre>\n<h3 id=\"getpageslinksandbacklinks\" tabindex=\"-1\"><code>getPagesLinksAndBacklinks</code></h3>\n<p>Get outgoing links and backlinks for the given pages in one call.<br>\nConvenience that runs getPagesLinks and getPagesBacklinks in parallel.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code> - Array of page titles</li>\n<li><code>options</code> - Options (namespace for both; backlinkLimit for backlinks only)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const links = await wiki.getPagesLinksAndBacklinks([&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;])\n</code></pre>\n<h3 id=\"getpagesource\" tabindex=\"-1\"><code>getPageSource</code></h3>\n<p>Get page content as wikitext source</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const source = await wiki.getPageSource(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagesummary\" tabindex=\"-1\"><code>getPageSummary</code></h3>\n<p>Get a page summary (extract, thumbnail, etc.)</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const summary = await wiki.getPageSummary(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagethumbnail\" tabindex=\"-1\"><code>getPageThumbnail</code></h3>\n<p>Get thumbnail image for a page.<br>\nUses the lead image (page summary) when available; otherwise falls back to the<br>\nfirst image on the page (e.g. infobox image).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const thumbnail = await wiki.getPageThumbnail(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getpagethumbnails\" tabindex=\"-1\"><code>getPageThumbnails</code></h3>\n<p>Get thumbnail URLs for multiple pages (lead image from each page).<br>\nUses the Action API pageimages in batches of 50.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code> - Page titles</li>\n<li><code>baseUrl</code> - Wiki base URL (e.g. <a href=\"https://en.wikipedia.org/\">https://en.wikipedia.org/</a>). Defaults to this.base</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const thumbnails = await wiki.getPageThumbnails([&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;])\n</code></pre>\n<h3 id=\"getrandompage\" tabindex=\"-1\"><code>getRandomPage</code></h3>\n<p>Get a random page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>format</code> - Format: ‘summary’, ‘html’, or ‘title’ (default: ‘summary’)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const random = await wiki.getRandomPage()\n</code></pre>\n<h3 id=\"getshortdescription\" tabindex=\"-1\"><code>getShortDescription</code></h3>\n<p>Get the short description for a page (from template or Wikidata).<br>\nUses the page summary API; results are cached to avoid repeated requests.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const description = await wiki.getShortDescription(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"transformwikitexttohtml\" tabindex=\"-1\"><code>transformWikitextToHtml</code></h3>\n<p>Transform wikitext to HTML</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>wikitext</code> - Wikitext content</li>\n<li><code>pageTitle</code> - Page title for context (optional)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const html = await wiki.transformWikitextToHtml(&quot;Hello '''world'''&quot;, &quot;Main_Page&quot;)\n</code></pre>\n<h2 id=\"revisions-and-diffs\" tabindex=\"-1\">Revisions and diffs</h2>\n<h3 id=\"getcombinedfeed\" tabindex=\"-1\"><code>getCombinedFeed</code></h3>\n<p>Get a combined feed of revisions from multiple users and/or pages.<br>\nReturns revisions that match ANY of the provided users OR pages, deduplicated and sorted by timestamp.<br>\nCaching is handled internally by getUserHistory and getPageHistory.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>options</code> - Configuration object</li>\n<li><code>options.userNames</code> - Array of usernames to include</li>\n<li><code>options.pageNames</code> - Array of page titles to include</li>\n<li><code>options.limit</code> - Maximum total number of revisions to return (default and max: PAGE_HISTORY_REVISIONS_PER_REQUEST)</li>\n<li><code>options.perSourceLimit</code> - Maximum revisions to request per page/user history source before merge</li>\n<li><code>options.after</code> - Map of source (page name or user name) → revision ID to fetch revisions older than (per source). Ensures every page/user keeps paginating.</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const revisions = await wiki.getCombinedFeed({\n  userNames: [&quot;Todepond&quot;, &quot;Samwalton9&quot;],\n  pageNames: [&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;],\n  limit: 20,\n})\n</code></pre>\n<h3 id=\"getdeltaclass\" tabindex=\"-1\"><code>getDeltaClass</code></h3>\n<p>Get CSS class name for delta (change size) indicator</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>delta</code> - Change size (positive, negative, or zero)</li>\n<li><code>withSign</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const className = wiki.getDeltaClass(42)\n</code></pre>\n<h3 id=\"getdifflineclass\" tabindex=\"-1\"><code>getDiffLineClass</code></h3>\n<p>Map compare API diff line type to a CSS class name.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>type</code> - Diff line type (0=context, 1=add, 2=remove, 3/4/5=change)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const className = wiki.getDiffLineClass(0)\n</code></pre>\n<h3 id=\"getdifflinesegments\" tabindex=\"-1\"><code>getDiffLineSegments</code></h3>\n<p>Split a diff line into character-level highlight segments.<br>\nConverts API byte-based highlight ranges into string segments that can be rendered with add/remove styles.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>line</code> - Diff line from compare API</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import type { FWDiffLine } from &quot;fakewiki/types&quot;\nconst line = {\n  type: 1,\n  text: &quot;Example text&quot;,\n  highlightRanges: [{ start: 0, length: 7, type: 0 }],\n} as FWDiffLine\nconst segments = wiki.getDiffLineSegments(line)\n</code></pre>\n<h3 id=\"getdiffsource\" tabindex=\"-1\"><code>getDiffSource</code></h3>\n<p>Get source diff for a revision by comparing it with its parent (previous) revision.<br>\nWhen there is no parent (e.g. first revision), returns a synthetic diff where<br>\nevery line is shown as added.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>revId</code> - Revision ID to diff</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const compare = await wiki.getDiffSource(&quot;Corsica Studios&quot;, 1337619110)\n</code></pre>\n<h3 id=\"getparentrevisionid\" tabindex=\"-1\"><code>getParentRevisionId</code></h3>\n<p>Get the parent (previous) revision ID for a revision on a page.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>revId</code> - Revision ID (we want the revision immediately older than this)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const parentId = await wiki.getParentRevisionId(&quot;Corsica Studios&quot;, 1337619110)\n</code></pre>\n<h3 id=\"getrecentchanges\" tabindex=\"-1\"><code>getRecentChanges</code></h3>\n<p>Get global recent changes from the wiki (any pages) via Action API list=recentchanges.<br>\nOptionally restrict to changes that “need review” (high revert risk) with rcshow=oresreview.<br>\nUses rctoponly so only the latest revision of each page is returned.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>options</code> - Configuration object</li>\n<li><code>options.limit</code> - Maximum number of changes to return (default 50, max 500)</li>\n<li><code>options.rccontinue</code> - Continuation token from a previous response for pagination</li>\n<li><code>options.onlyNeedsReview</code> - If true, pass rcshow=oresreview so the server returns only high revert risk / “needs review” edits (default false)</li>\n<li><code>options.rcstart</code> - Timestamp to start enumerating from (with rcdir=older, must be later than rcend)</li>\n<li><code>options.rcend</code> - Timestamp to end enumerating (with rcdir=older, must be earlier than rcstart)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const changes = await wiki.getRecentChanges()\n</code></pre>\n<h3 id=\"getrevisiondiff\" tabindex=\"-1\"><code>getRevisionDiff</code></h3>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code></li>\n<li><code>revId</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const compare = await wiki.getRevisionDiff(&quot;Corsica Studios&quot;, 1337619110)\n</code></pre>\n<h3 id=\"getrevisionhtml\" tabindex=\"-1\"><code>getRevisionHtml</code></h3>\n<p>Get HTML for a specific revision.<br>\nUses the MediaWiki REST API endpoint: GET revision/{id}/html.<br>\nFalls back to the Wikimedia REST API page/html/{title}/{revision} if needed.<br>\nUses caching to avoid re-fetching the same revision.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title (used for Wikimedia fallback and for API compatibility)</li>\n<li><code>revId</code> - Revision ID</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const html = await wiki.getRevisionHtml(&quot;Wet Leg&quot;, 1337619110)\n</code></pre>\n<h3 id=\"getrevisionsource\" tabindex=\"-1\"><code>getRevisionSource</code></h3>\n<p>Get wikitext source for a revision by ID.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revId</code> - Revision ID</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const source = await wiki.getRevisionSource(1337619110)\n</code></pre>\n<h3 id=\"getrevisiontags\" tabindex=\"-1\"><code>getRevisionTags</code></h3>\n<p>Fetch edit tags for given revision IDs via Action API.<br>\nUse for revisions from sources that don’t include tags (e.g. page history, related changes).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revIds</code> - Revision IDs to fetch tags for</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const tags = await wiki.getRevisionTags([1337619110])\n</code></pre>\n<h3 id=\"grouprevisionsbydate\" tabindex=\"-1\"><code>groupRevisionsByDate</code></h3>\n<p>Group revisions by calendar date for watchlist-style rendering.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisions</code> - Revisions to group (typically already newest-first)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import type { FWRevision } from &quot;fakewiki/types&quot;\nconst revs: FWRevision[] = [\n  {\n    id: 1337619110,\n    timestamp: &quot;2026-02-26T10:30:00Z&quot;,\n    user: { name: &quot;Samwalton9&quot; },\n    delta: 42,\n    comment: &quot;Example summary&quot;,\n    pageName: &quot;Wet Leg&quot;,\n  },\n  {\n    id: 1337619100,\n    timestamp: &quot;2026-02-26T09:15:00Z&quot;,\n    user: { name: &quot;Todepond&quot; },\n    delta: -5,\n    comment: &quot;Another example&quot;,\n    pageName: &quot;Confidence Man (band)&quot;,\n  },\n]\nconst groups = wiki.groupRevisionsByDate(revs)\n</code></pre>\n<h2 id=\"structured-deltas\" tabindex=\"-1\">Structured deltas</h2>\n<h3 id=\"getedittypesdebug\" tabindex=\"-1\"><code>getEditTypesDebug</code></h3>\n<p>Get diff debug payload from edit-types API (full diff, tree diff, simple diff for comparison).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>options</code> - Optional lang and content_type (default wikitext)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const debug = await wiki.getEditTypesDebug(1337619110, { lang: &quot;en&quot; })\n</code></pre>\n<h3 id=\"getedittypesdetails\" tabindex=\"-1\"><code>getEditTypesDetails</code></h3>\n<p>Get structured diff details from edit-types API (context, node-edits, text-edits).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>options</code> - Optional lang and content_type (default wikitext)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const details = await wiki.getEditTypesDetails(1337619110, { lang: &quot;en&quot; })\n</code></pre>\n<h3 id=\"getedittypessummary\" tabindex=\"-1\"><code>getEditTypesSummary</code></h3>\n<p>Get simple diff summary from edit-types API (counts per change type per action).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>options</code> - Optional lang and content_type (default wikitext)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const summary = await wiki.getEditTypesSummary(1337619110, { lang: &quot;en&quot; })\n</code></pre>\n<h3 id=\"getstructureddeltalevelindex\" tabindex=\"-1\"><code>getStructuredDeltaLevelIndex</code></h3>\n<p>Public for snippet logic: significance level index (0 = most significant).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>type</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const levelIndex = wiki.getStructuredDeltaLevelIndex(&quot;Sentence&quot;)\n</code></pre>\n<h3 id=\"getstructureddeltasfromrevision\" tabindex=\"-1\"><code>getStructuredDeltasFromRevision</code></h3>\n<p>Get computed structured-delta output for a revision ID in one call.<br>\nFetches edit-types summary, then computes inline segments with configurable settings.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>options</code> - Optional edit-types API options (<code>lang</code>, <code>content_type</code>) and structured-delta settings</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const deltas = await wiki.getStructuredDeltasFromRevision(1337619110, { lang: &quot;en&quot; })\n</code></pre>\n<h3 id=\"getstructureddeltasfromsummary\" tabindex=\"-1\"><code>getStructuredDeltasFromSummary</code></h3>\n<p>Compute structured-delta output (segments + candidates) from a normalized summary.<br>\nReturns null when summary is empty or disabled via <code>improvedDeltaEnabled</code>.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>summary</code> - Pre-normalized summary (type -&gt; action -&gt; count)</li>\n<li><code>options</code> - Optional structured-delta settings overrides</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import type { FWEditTypesDiffSummary } from &quot;fakewiki/types&quot;\nconst summary = {\n  Sentence: { change: 1 },\n  Punctuation: { remove: 1 },\n} as FWEditTypesDiffSummary\nconst structuredDeltas = wiki.getStructuredDeltasFromSummary(summary, {\n  improvedDeltaEnabled: true,\n  relativeDetailLevelEnabled: true,\n  smartFilteringEnabled: true,\n})\n</code></pre>\n<h3 id=\"normalizestructureddeltasummary\" tabindex=\"-1\"><code>normalizeStructuredDeltaSummary</code></h3>\n<p>Normalize edit-types response into summary shape used for structured-delta computation.<br>\nAccepts either root summary object or payload containing a <code>summary</code> property.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>raw</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const summary = wiki.normalizeStructuredDeltaSummary(\n  JSON.parse(\n    '{&quot;summary&quot;:{&quot;Sentence&quot;:{&quot;change&quot;:2,&quot;remove&quot;:1},&quot;Punctuation&quot;:{&quot;remove&quot;:1},&quot;Whitespace&quot;:{&quot;change&quot;:1},&quot;Comment&quot;:{&quot;insert&quot;:&quot;2&quot;}},&quot;debug&quot;:{&quot;traceId&quot;:&quot;demo&quot;}}',\n  ) as Record&lt;string, unknown&gt;,\n)\n</code></pre>\n<h2 id=\"search\" tabindex=\"-1\">Search</h2>\n<h3 id=\"getmorelikepages\" tabindex=\"-1\"><code>getMoreLikePages</code></h3>\n<p>Find pages related to one or more seed pages using CirrusSearch <code>morelike:</code>.<br>\nUses Action API search (<code>action=query&amp;list=search</code>) with <code>srsearch=morelike:...</code>.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitles</code> - Seed page titles used to construct the morelike query</li>\n<li><code>options</code> - Optional search options (limit, offset, and namespace)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const related = await wiki.getMoreLikePages(\n  [&quot;Wet Leg&quot;, &quot;Rizzle Kicks&quot;, &quot;Jade Thirlwall&quot;],\n  { limit: 10 },\n)\n</code></pre>\n<h3 id=\"searchpages\" tabindex=\"-1\"><code>searchPages</code></h3>\n<p>Full-text search across page titles and content</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>query</code> - Search query</li>\n<li><code>limit</code> - Maximum results (default: DEFAULT_SEARCH_LIMIT)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const pageResults = await wiki.searchPages(&quot;Wet Leg&quot;, 20)\n</code></pre>\n<h3 id=\"searchtitles\" tabindex=\"-1\"><code>searchTitles</code></h3>\n<p>Search for pages by title (autocomplete-style)</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>query</code> - Search query</li>\n<li><code>limit</code> - Maximum results (default: DEFAULT_SEARCH_LIMIT)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const titleResults = await wiki.searchTitles(&quot;Wet Leg&quot;, 20)\n</code></pre>\n<h3 id=\"searchusers\" tabindex=\"-1\"><code>searchUsers</code></h3>\n<p>Search for users by username (without avatars).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>query</code> - Search query (username or part of username)</li>\n<li><code>limit</code> - Maximum results (default: DEFAULT_SEARCH_LIMIT)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const users = await wiki.searchUsers(&quot;Samwalton9&quot;, 20)\n</code></pre>\n<h3 id=\"searchuserswithavatars\" tabindex=\"-1\"><code>searchUsersWithAvatars</code></h3>\n<p>Search for users by username and fetch their avatars.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>query</code> - Search query (username or part of username)</li>\n<li><code>limit</code> - Maximum results (default: DEFAULT_SEARCH_LIMIT)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const users = await wiki.searchUsersWithAvatars(&quot;Samwalton9&quot;, 20)\n</code></pre>\n<h2 id=\"users\" tabindex=\"-1\">Users</h2>\n<h3 id=\"getdaysofactivity\" tabindex=\"-1\"><code>getDaysOfActivity</code></h3>\n<p>Calculate days of activity from registration date</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>registrationDate</code> - ISO timestamp string (e.g., “2007-06-07T16:36:03Z”)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const days = wiki.getDaysOfActivity(&quot;2025-02-26T10:30:00Z&quot;)\n</code></pre>\n<h3 id=\"getuseravatar\" tabindex=\"-1\"><code>getUserAvatar</code></h3>\n<p>Infer a user avatar image from their user page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const avatarUrl = await wiki.getUserAvatar(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getusercategory\" tabindex=\"-1\"><code>getUserCategory</code></h3>\n<p>Get a user’s category (cache-aware main entry point).<br>\nReads from category cache when available; otherwise fetches user info and caches the result.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to classify</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const category = await wiki.getUserCategory(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getusercategorydisplay\" tabindex=\"-1\"><code>getUserCategoryDisplay</code></h3>\n<p>Return display config (icon + color) for a user’s category. Uses cache when available;<br>\notherwise fetches user info and caches the category, then returns the display config.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to look up</li>\n<li><code>options</code> - Optional overrides; <code>userTypeConfig</code> merges with the default per-category display config</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const display = await wiki.getUserCategoryDisplay(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getuserhistory\" tabindex=\"-1\"><code>getUserHistory</code></h3>\n<p>Get user contribution history (revisions made by a user)<br>\nUses caching to avoid fetching the same data twice.<br>\nUses older_than/newer_than cursors for pagination and filtering.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username</li>\n<li><code>options</code> - Options</li>\n<li><code>options.limit</code> - Limit (default: DEFAULT_USER_CONTRIBS_LIMIT, max: USER_CONTRIBS_MAX_LIMIT)</li>\n<li><code>options.older_than</code> - Timestamp - for explicit pagination</li>\n<li><code>options.newer_than</code> - Timestamp - for explicit pagination</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const history = await wiki.getUserHistory(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getuserinfo\" tabindex=\"-1\"><code>getUserInfo</code></h3>\n<p>Get user information including edit count, registration date, and account type<br>\nResults are cached in memory to avoid repeated API calls for the same user.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username or IP address</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const userInfo = await wiki.getUserInfo(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getusershistory\" tabindex=\"-1\"><code>getUsersHistory</code></h3>\n<p>Get contributions for multiple users by calling getUserHistory for each.<br>\nUses caching to avoid fetching the same data twice.<br>\nUses bounded concurrency (same as getCombinedFeed user branch; Wikimedia: few concurrent Action requests).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userNames</code> - Array of usernames</li>\n<li><code>options</code> - Options</li>\n<li><code>options.limit</code> - Limit per user (default: DEFAULT_USER_CONTRIBS_LIMIT)</li>\n<li><code>options.older_than</code> - Timestamp - for explicit pagination</li>\n<li><code>options.newer_than</code> - Timestamp - for explicit pagination</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const histories = await wiki.getUsersHistory([&quot;Todepond&quot;, &quot;Samwalton9&quot;])\n</code></pre>\n<h3 id=\"getusersinfo\" tabindex=\"-1\"><code>getUsersInfo</code></h3>\n<p>Batch-fetch user information via Action API <code>list=users</code>, including <code>groups</code> and<br>\n<code>implicitgroups</code> (for bot detection). Requests at most 50 names per HTTP call.<br>\nDuplicate names in the input are ignored after the first occurrence; the returned<br>\nobject has one key per unique trimmed username.<br>\nResults are merged into the same in-memory cache as {@link getUserInfo}.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userNames</code> - Usernames or IP addresses (empty strings skipped)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const byName = await wiki.getUsersInfo([&quot;Samwalton9&quot;, &quot;Todepond&quot;])\n</code></pre>\n<h3 id=\"isipaddress\" tabindex=\"-1\"><code>isIPAddress</code></h3>\n<p>Check if a username is an IP address</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to check</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const isIp = wiki.isIPAddress(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"istemporaryaccount\" tabindex=\"-1\"><code>isTemporaryAccount</code></h3>\n<p>Check if a username is a temporary account (starts with ~)</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to check</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const isTemp = wiki.isTemporaryAccount(&quot;Samwalton9&quot;)\n</code></pre>\n<h2 id=\"recommendations\" tabindex=\"-1\">Recommendations</h2>\n<h3 id=\"getlistbuilding\" tabindex=\"-1\"><code>getListBuilding</code></h3>\n<p>Get a list of articles related to a seed page from the list-building API.<br>\nCombines results from readers, content (links), and morelike models (serpentine order).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>lang</code> - Language code (e.g. “en”)</li>\n<li><code>options</code> - Optional page title (seed), QID, and per-source result count (default 10)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const list = await wiki.getListBuilding(&quot;en&quot;, { pageTitle: &quot;Wet Leg&quot; })\n</code></pre>\n<h3 id=\"getmultipagelistbuilding\" tabindex=\"-1\"><code>getMultiPageListBuilding</code></h3>\n<p>Get list-building results for multiple seed pages. Returns the final aggregated list<br>\ndeduped by recommended page and sorted by quality (best first). Optionally pass onLoad<br>\nto receive progressively complete lists (each call is the full current list, same shape).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>lang</code> - Language code (e.g. “en”)</li>\n<li><code>pageTitles</code> - Seed page titles (deduplicated; empty titles skipped)</li>\n<li><code>options</code> - Optional k and onLoad callback (always processes one seed page at a time)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const list = await wiki.getMultiPageListBuilding(&quot;en&quot;, [&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;])\n</code></pre>\n<h3 id=\"getrelatedchanges\" tabindex=\"-1\"><code>getRelatedChanges</code></h3>\n<p>Get related changes using the Action API feedrecentchanges (1-2 requests total).<br>\nReturns recent edits on pages linked from the target (outgoing) and/or pages that link to the target (incoming).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>targetPageName</code> - Page title to get related changes for</li>\n<li><code>options</code> - showOutgoing: changes on pages the target links to (default true); showIncoming: changes on pages that link to the target (default true); limit: max items per direction 1-50 (default 50); days: 1-30 (default 7); from: optional lower-bound timestamp; to: optional upper-bound timestamp (useful for older-page pagination)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const changes = await wiki.getRelatedChanges(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"gettoprelatedchanges\" tabindex=\"-1\"><code>getTopRelatedChanges</code></h3>\n<p>Get related changes from multiple seed pages, merged and filtered to the top N% by score.<br>\nCounts and score are per-page: “which feeds this page appears in” (any revision). Same<br>\nfeedCountBidirectional/Outgoing/Backlink and score are shown on every revision of that page.<br>\nUses scoreMultipliers (default bidirectional×4, outgoing×2, backlink×1). No extra API calls.<br>\nOrder is preserved (by timestamp desc); no extra sorting after filtering.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code></li>\n<li><code>options</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const topChanges = await wiki.getTopRelatedChanges(\n  [&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;],\n  { percentage: 1 },\n)\n</code></pre>\n<h3 id=\"gettoprelatedpages\" tabindex=\"-1\"><code>getTopRelatedPages</code></h3>\n<p>Get the list of page titles that appear in the top N% of related changes by score.<br>\nSame options as getTopRelatedChanges; returns unique page names in order of first appearance,<br>\neach with the score from the first change that introduced that page (static per page),<br>\nplus the changes that were retrieved as part of the scoring process (with sourcePageNames and link-type info).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageNames</code></li>\n<li><code>options</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const topPages = await wiki.getTopRelatedPages(\n  [&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;],\n  { percentage: 1 },\n)\n</code></pre>\n<h2 id=\"predictions\" tabindex=\"-1\">Predictions</h2>\n<h3 id=\"getdamagingprediction\" tabindex=\"-1\"><code>getDamagingPrediction</code></h3>\n<p>Get damaging prediction for a single revision from Lift Wing API</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const damaging = await wiki.getDamagingPrediction(1337619110)\n</code></pre>\n<h3 id=\"getdamagingpredictions\" tabindex=\"-1\"><code>getDamagingPredictions</code></h3>\n<p>Get damaging predictions for multiple revisions in parallel</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionIds</code> - Array of revision IDs</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const damagingMap = await wiki.getDamagingPredictions([1337619110])\n</code></pre>\n<h3 id=\"getgoodfaithprediction\" tabindex=\"-1\"><code>getGoodfaithPrediction</code></h3>\n<p>Get goodfaith prediction for a single revision from Lift Wing API</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionId</code> - Revision ID</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const goodfaith = await wiki.getGoodfaithPrediction(1337619110)\n</code></pre>\n<h3 id=\"getgoodfaithpredictions\" tabindex=\"-1\"><code>getGoodFaithPredictions</code></h3>\n<p>Get goodfaith predictions for multiple revisions in parallel</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionIds</code> - Array of revision IDs</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const goodfaithMap = await wiki.getGoodFaithPredictions([1337619110])\n</code></pre>\n<h3 id=\"getreferenceneedprediction\" tabindex=\"-1\"><code>getReferenceNeedPrediction</code></h3>\n<p>Get reference need prediction for a revision from Lift Wing.<br>\nPredicts the proportion of uncited sentences that need citations (0-1).<br>\nUse for surfacing “needs reference check” flags when tags are unavailable.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revId</code> - Revision ID</li>\n<li><code>lang</code> - Language code (e.g. “en”). If not provided, derived from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const prediction = await wiki.getReferenceNeedPrediction(1337619110, &quot;en&quot;)\n</code></pre>\n<h3 id=\"getrevisionpredictions\" tabindex=\"-1\"><code>getRevisionPredictions</code></h3>\n<p>Get predictions for multiple revisions and one/many Lift Wing models.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionIds</code> - Array of revision IDs</li>\n<li><code>models</code> - Lift Wing model slug(s). Defaults to damaging+goodfaith.</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const predictions = await wiki.getRevisionPredictions(\n  [1337619110],\n  [&quot;damaging&quot;, &quot;goodfaith&quot;, &quot;revertrisk&quot;, &quot;revertrisk-multilingual&quot;],\n)\n</code></pre>\n<h3 id=\"getrevisionpredictionsfromores\" tabindex=\"-1\"><code>getRevisionPredictionsFromOres</code></h3>\n<p>Get damaging and goodfaith predictions from ORES (single request per batch).<br>\nORES is a scoring aggregator; one call returns both models. Prefer this when<br>\nLift Wing is unavailable or for lower latency on batch requests.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>revisionIds</code> - Array of revision IDs (batched internally; ORES recommends ≤20 per request, ≤4 parallel)</li>\n<li><code>wiki</code> - Wiki code (e.g., “enwiki”). If not provided, extracted from base URL</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const predictions = await wiki.getRevisionPredictionsFromOres([1337619110])\n</code></pre>\n<h3 id=\"gettonecheckforrevision\" tabindex=\"-1\"><code>getToneCheckForRevision</code></h3>\n<p>Get Tone Check prediction for a revision by comparing it with its parent.<br>\nFetches the diff, extracts only changed lines (no context), and runs tone check.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>revId</code> - Revision ID to check</li>\n<li><code>options</code> - Optional lang (default from wiki) and pageTitle (default pageName)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const prediction = await wiki.getToneCheckForRevision(&quot;Corsica Studios&quot;, 1337619110, {\n  lang: &quot;en&quot;,\n  pageTitle: &quot;Corsica Studios&quot;,\n})\n</code></pre>\n<h3 id=\"gettonecheckprediction\" tabindex=\"-1\"><code>getToneCheckPrediction</code></h3>\n<p>Get Tone Check prediction from Lift Wing edit-check model.<br>\nDetects promotional, derogatory, or subjective language in text.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>originalText</code> - Text before the edit</li>\n<li><code>modifiedText</code> - Text after the edit (the new content to check)</li>\n<li><code>options</code> - Optional lang (default from wiki) and pageTitle (default “”)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const prediction = await wiki.getToneCheckPrediction(\n  &quot;The band formed in 2020.&quot;,\n  &quot;The band is the most talented and revolutionary group of our generation.&quot;,\n  { lang: &quot;en&quot;, pageTitle: &quot;Example band&quot; },\n)\n</code></pre>\n<h2 id=\"suggestions\" tabindex=\"-1\">Suggestions</h2>\n<h3 id=\"getveaddreferencesuggestions\" tabindex=\"-1\"><code>getVeAddReferenceSuggestions</code></h3>\n<p>Simulate VE AddReference suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeAddReferenceSuggestions(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getvecitationneededsuggestions\" tabindex=\"-1\"><code>getVeCitationNeededSuggestions</code></h3>\n<p>Simulate VE CitationNeeded suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeCitationNeededSuggestions(&quot;United Kingdom&quot;)\n</code></pre>\n<h3 id=\"getveconvertreferencesuggestions\" tabindex=\"-1\"><code>getVeConvertReferenceSuggestions</code></h3>\n<p>Simulate VE ConvertReference suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n<li><code>options</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeConvertReferenceSuggestions(&quot;Wet Leg&quot;, {\n  strict: &quot;url-only&quot;,\n})\n</code></pre>\n<h3 id=\"getvedisambiguationsuggestions\" tabindex=\"-1\"><code>getVeDisambiguationSuggestions</code></h3>\n<p>Simulate VE Disambiguation suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeDisambiguationSuggestions(&quot;United Kingdom&quot;)\n</code></pre>\n<h3 id=\"getvedoubleboldsuggestions\" tabindex=\"-1\"><code>getVeDoubleBoldSuggestions</code></h3>\n<p>Simulate VE DoubleBold suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeDoubleBoldSuggestions(&quot;Glossary of mathematics&quot;)\n</code></pre>\n<h3 id=\"getveduplicatelinksuggestions\" tabindex=\"-1\"><code>getVeDuplicateLinkSuggestions</code></h3>\n<p>Simulate VE DuplicateLink suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n<li><code>options</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeDuplicateLinkSuggestions(&quot;Little Mix&quot;, {\n  scope: &quot;paragraph&quot;,\n})\n</code></pre>\n<h3 id=\"getveexternallinksuggestions\" tabindex=\"-1\"><code>getVeExternalLinkSuggestions</code></h3>\n<p>Simulate VE ExternalLink suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeExternalLinkSuggestions(&quot;Live coding&quot;)\n</code></pre>\n<h3 id=\"getvefakeheadingsuggestions\" tabindex=\"-1\"><code>getVeFakeHeadingSuggestions</code></h3>\n<p>Simulate VE FakeHeading suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeFakeHeadingSuggestions(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getveimagecaptionsuggestions\" tabindex=\"-1\"><code>getVeImageCaptionSuggestions</code></h3>\n<p>Simulate VE ImageCaption suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeImageCaptionSuggestions(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getveredirectsuggestions\" tabindex=\"-1\"><code>getVeRedirectSuggestions</code></h3>\n<p>Simulate VE Redirect suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeRedirectSuggestions(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getverequiredtemplateparamsuggestions\" tabindex=\"-1\"><code>getVeRequiredTemplateParamSuggestions</code></h3>\n<p>Simulate VE RequiredTemplateParam suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeRequiredTemplateParamSuggestions(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getvesuggestedlinksuggestions\" tabindex=\"-1\"><code>getVeSuggestedLinkSuggestions</code></h3>\n<p>Simulate VE SuggestedLink suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n<li><code>options</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeSuggestedLinkSuggestions(&quot;Wet Leg&quot;, { threshold: 0.8 })\n</code></pre>\n<h3 id=\"getvetextmatchsuggestions\" tabindex=\"-1\"><code>getVeTextMatchSuggestions</code></h3>\n<p>Simulate VE TextMatch suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code> - Page title to evaluate</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeTextMatchSuggestions(&quot;Ips pini&quot;)\n</code></pre>\n<h3 id=\"getvetonesuggestions\" tabindex=\"-1\"><code>getVeToneSuggestions</code></h3>\n<p>Simulate VE Tone suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code> - Page title to evaluate</li>\n<li><code>options</code> - Optional threshold and max candidates</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeToneSuggestions(&quot;Artificial intelligence&quot;, {\n  threshold: 0.8,\n  maxCandidates: 20,\n})\n</code></pre>\n<h3 id=\"getveyearlinksuggestions\" tabindex=\"-1\"><code>getVeYearLinkSuggestions</code></h3>\n<p>Simulate VE YearLink suggestions for editor-open behavior (enwiki).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageTitle</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const suggestions = await wiki.getVeYearLinkSuggestions(&quot;United States&quot;)\n</code></pre>\n<h2 id=\"formatting\" tabindex=\"-1\">Formatting</h2>\n<h3 id=\"formatdate\" tabindex=\"-1\"><code>formatDate</code></h3>\n<p>Format date as “DD Month YYYY” or “DD.MM.YY”.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code></li>\n<li><code>style</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const formatted = wiki.formatDate(&quot;2026-02-26T10:30:00Z&quot;, &quot;long&quot;)\n</code></pre>\n<h3 id=\"formatdelta\" tabindex=\"-1\"><code>formatDelta</code></h3>\n<p>Format a revision size delta using watchlist notation.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>delta</code> - Byte delta for a revision; null/NaN are treated as zero</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const delta = wiki.formatDelta(42)\n</code></pre>\n<h3 id=\"formatnicerelativetimestamp\" tabindex=\"-1\"><code>formatNiceRelativeTimestamp</code></h3>\n<p>Format relative time using the standard watchlist display preset.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code> - ISO timestamp, epoch milliseconds, or Date instance</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const relativeNice = wiki.formatNiceRelativeTimestamp(&quot;2026-02-26T10:30:00Z&quot;)\n</code></pre>\n<h3 id=\"formatrelativetimestamp\" tabindex=\"-1\"><code>formatRelativeTimestamp</code></h3>\n<p>Format relative time (e.g. “2 minutes ago”, “3 days ago”).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code> - ISO timestamp string, Date, or epoch</li>\n<li><code>options</code> - Formatting options for different time periods</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const relative = wiki.formatRelativeTimestamp(&quot;2026-02-26T10:30:00Z&quot;, {\n  seconds: &quot;words&quot;,\n  minutes: &quot;minutes&quot;,\n  hours: &quot;hours&quot;,\n  days: &quot;days&quot;,\n  weeks: &quot;weeks&quot;,\n  months: &quot;months&quot;,\n  years: &quot;years&quot;,\n})\n</code></pre>\n<h3 id=\"formattime\" tabindex=\"-1\"><code>formatTime</code></h3>\n<p>Format time as HH:MM.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const time = wiki.formatTime(&quot;2026-02-26T10:30:00Z&quot;)\n</code></pre>\n<h3 id=\"geteditsummaryhtml\" tabindex=\"-1\"><code>getEditSummaryHtml</code></h3>\n<p>Get the HTML representation of an edit summary</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>summary</code> - Edit summary to get the HTML representation of</li>\n<li><code>pageName</code> - Page name</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const html = await wiki.getEditSummaryHtml(&quot;Fix typo&quot;, &quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"gettablefromeditsummary\" tabindex=\"-1\"><code>getTableFromEditSummary</code></h3>\n<p>Parse a toolbar-style edit summary into a table of contents</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>editSummary</code> - Edit summary to parse</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const table = wiki.getTableFromEditSummary(\n  &quot;Alter: template type, title. Add: journal, authors 1-1. Removed parameters. Some additions/deletions were parameter name changes. | [[User:UcuchaBot|Use this bot]]. [[User talk:Ucucha|Report bugs]]. | Suggested by Abductive | #UCB_toolbar&quot;,\n)\n</code></pre>\n<h3 id=\"istoday\" tabindex=\"-1\"><code>isToday</code></h3>\n<p>Check whether a timestamp falls on today in local time.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const today = wiki.isToday(&quot;2026-02-26T10:30:00Z&quot;)\n</code></pre>\n<h3 id=\"parsetoolbareditsummary\" tabindex=\"-1\"><code>parseToolbarEditSummary</code></h3>\n<p>Parse a toolbar edit summary into structured parts</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>editSummary</code> - Edit summary to parse</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const parsed = wiki.parseToolbarEditSummary(\n  &quot;Alter: template type, title. Add: journal, authors 1-1. Removed parameters. Some additions/deletions were parameter name changes. | [[User:UcuchaBot|Use this bot]]. [[User talk:Ucucha|Report bugs]]. | Suggested by Abductive | #UCB_toolbar&quot;,\n)\n</code></pre>\n<h3 id=\"preprocesseditsummary\" tabindex=\"-1\"><code>preprocessEditSummary</code></h3>\n<p>Preprocess an edit summary’s special wikitext variant to get it ready for transformation.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>summary</code> - Edit summary to preprocess</li>\n<li><code>pageName</code> - Page name</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const preprocessed = wiki.preprocessEditSummary(&quot;/* History *&quot; + &quot;/ Fix typo&quot;, &quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"todatekey\" tabindex=\"-1\"><code>toDateKey</code></h3>\n<p>Convert timestamp to YYYY-MM-DD key for grouping.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>timestamp</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const dateKey = wiki.toDateKey(&quot;2026-02-26T10:30:00Z&quot;)\n</code></pre>\n<h2 id=\"urls\" tabindex=\"-1\">URLs</h2>\n<h3 id=\"encodeforurl\" tabindex=\"-1\"><code>encodeForUrl</code></h3>\n<p>Encode a page title for URL usage</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>slug</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const encoded = wiki.encodeForUrl(&quot;&quot;)\n</code></pre>\n<h3 id=\"getasseturlfromuploadurl\" tabindex=\"-1\"><code>getAssetUrlFromUploadUrl</code></h3>\n<p>Get file page URL from an upload URL<br>\nExtracts the filename from a Wikimedia Commons upload URL and returns a link to the file page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>uploadUrl</code> - Upload URL</li>\n<li><code>pageName</code> - Page name where the file is used</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getAssetUrlFromUploadUrl(\n  &quot;https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/File.jpg/640px-File.jpg&quot;,\n  &quot;Wet Leg&quot;,\n)\n</code></pre>\n<h3 id=\"getediturl\" tabindex=\"-1\"><code>getEditUrl</code></h3>\n<p>Get URL for editing a page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>sectionTitle</code> - Optional section name (e.g. from edit summary like /</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getEditUrl(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"gethistoryurl\" tabindex=\"-1\"><code>getHistoryUrl</code></h3>\n<p>Get URL for page history</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getHistoryUrl(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getmediawikibase\" tabindex=\"-1\"><code>getMediawikiBase</code></h3>\n<p>Get the base URL for the MediaWiki REST API</p>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const mediawikiBase = wiki.getMediawikiBase()\n</code></pre>\n<h3 id=\"getpageurl\" tabindex=\"-1\"><code>getPageUrl</code></h3>\n<p>Get URL for a page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getPageUrl(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getrevisionurl\" tabindex=\"-1\"><code>getRevisionUrl</code></h3>\n<p>Get URL for viewing a revision diff</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>id</code> - Revision ID</li>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getRevisionUrl(1337619110, &quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getrevisionviewurl\" tabindex=\"-1\"><code>getRevisionViewUrl</code></h3>\n<p>Get URL for viewing a specific revision (page content at that revision).<br>\nUses oldid= which shows the revision’s content (not the diff).</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>id</code> - Revision ID</li>\n<li><code>pageName</code> - Page title</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getRevisionViewUrl(1337619110, &quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getthankurl\" tabindex=\"-1\"><code>getThankUrl</code></h3>\n<p>Get URL for thanking a user for a revision</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>id</code> - Revision ID</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getThankUrl(1337619110)\n</code></pre>\n<h3 id=\"getusercontribsurl\" tabindex=\"-1\"><code>getUserContribsUrl</code></h3>\n<p>Get URL for user contributions</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getUserContribsUrl(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getusertalkurl\" tabindex=\"-1\"><code>getUserTalkUrl</code></h3>\n<p>Get URL for user talk page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getUserTalkUrl(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getuserurl\" tabindex=\"-1\"><code>getUserUrl</code></h3>\n<p>Get URL for a user page</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const url = wiki.getUserUrl(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getwikimediabase\" tabindex=\"-1\"><code>getWikimediaBase</code></h3>\n<p>Get the base URL for the Wikimedia REST API</p>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const wikimediaBase = wiki.getWikimediaBase()\n</code></pre>\n<h2 id=\"requests\" tabindex=\"-1\">Requests</h2>\n<h3 id=\"createresult\" tabindex=\"-1\"><code>createResult</code></h3>\n<p>Create a new Result instance with default values</p>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const result = wiki.createResult()\n</code></pre>\n<h3 id=\"createresults\" tabindex=\"-1\"><code>createResults</code></h3>\n<p>Create multiple Result instances</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>count</code> - Number of results to create</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const results = wiki.createResults(3)\n</code></pre>\n<h3 id=\"runwithconcurrency\" tabindex=\"-1\"><code>runWithConcurrency</code></h3>\n<p>Run async tasks with a concurrency limit; returns results in input order.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>items</code></li>\n<li><code>concurrency</code></li>\n<li><code>fn</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const results = await wiki.runWithConcurrency([1, 2, 3], 2, async (item) =&gt; item)\n</code></pre>\n<h2 id=\"cache-and-diagnostics\" tabindex=\"-1\">Cache and diagnostics</h2>\n<h3 id=\"clearlistbuildingcache\" tabindex=\"-1\"><code>clearListBuildingCache</code></h3>\n<p>Clear the list-building cache so the next getListBuilding / getMultiPageListBuilding<br>\ncalls re-fetch from the API. Use when the user explicitly requests fresh recommendations.</p>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">wiki.clearListBuildingCache()\n</code></pre>\n<h3 id=\"clearpagehistorycache\" tabindex=\"-1\"><code>clearPageHistoryCache</code></h3>\n<p>Clear the page history cache for a page (or all pages if no name given).<br>\nUse when you need fresh data, e.g. when opening the inline history view.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code></li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">wiki.clearPageHistoryCache(&quot;Wet Leg&quot;)\n</code></pre>\n<h3 id=\"getcachedusercategory\" tabindex=\"-1\"><code>getCachedUserCategory</code></h3>\n<p>Read a user’s category from cache (for UI keys/test ids). Returns null if not yet loaded.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to look up</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const category = wiki.getCachedUserCategory(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getcachedusercategorydisplay\" tabindex=\"-1\"><code>getCachedUserCategoryDisplay</code></h3>\n<p>Return display config (icon + color) for a user’s category from cache only.<br>\nReturns null if the user is not in the cache. Use in templates when the feed has already<br>\npopulated the cache (e.g. via getUserCategory in feed hooks). For on-demand fetch use<br>\ngetUserCategoryDisplay instead.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>userName</code> - Username to look up</li>\n<li><code>options</code> - Optional overrides; <code>userTypeConfig</code> merges with the default per-category display config</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const display = wiki.getCachedUserCategoryDisplay(&quot;Samwalton9&quot;)\n</code></pre>\n<h3 id=\"getparentrevisionidfromcache\" tabindex=\"-1\"><code>getParentRevisionIdFromCache</code></h3>\n<p>Get the parent (previous) revision ID for a revision on a page from cache only.<br>\nDoes not trigger any network request.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>pageName</code> - Page title</li>\n<li><code>revId</code> - Revision ID to look up in the cached page history</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const parentId = wiki.getParentRevisionIdFromCache(&quot;Wet Leg&quot;, 1337619110)\n</code></pre>\n<h3 id=\"inspecthistorycache\" tabindex=\"-1\"><code>inspectHistoryCache</code></h3>\n<p>Inspect cached history revisions and coverage metadata.<br>\nUseful for debugging pagination and cache behavior in prototypes.</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>options</code> - Optional filters for specific page/user keys</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const snapshot = wiki.inspectHistoryCache({\n  pageNames: [&quot;Wet Leg&quot;, &quot;Confidence Man (band)&quot;],\n  userNames: [&quot;Todepond&quot;, &quot;Samwalton9&quot;],\n})\n</code></pre>\n<h2 id=\"persistence\" tabindex=\"-1\">Persistence</h2>\n<h3 id=\"getstoragekey\" tabindex=\"-1\"><code>getStorageKey</code></h3>\n<p>Generate a storage key for a prototype</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>prototypeName</code> - Name of the prototype (e.g., “PageFeed”, “CustomPageFeed”)</li>\n<li><code>keyName</code> - Name of the key (e.g., “searchQuery”, “pageName”)</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const key = wiki.getStorageKey(&quot;PageFeed&quot;, &quot;searchQuery&quot;)\n</code></pre>\n<h3 id=\"getstoragekeys\" tabindex=\"-1\"><code>getStorageKeys</code></h3>\n<p>Generate multiple storage keys for a prototype</p>\n<p><strong>Parameters</strong></p>\n<ul>\n<li><code>prototypeName</code> - Name of the prototype</li>\n<li><code>keyName</code> - Base name of the key</li>\n<li><code>count</code> - Number of keys to generate</li>\n</ul>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const keys = wiki.getStorageKeys(&quot;PageFeed&quot;, &quot;searchQuery&quot;, 3)\n</code></pre>\n<h2 id=\"hooks\" tabindex=\"-1\">Hooks</h2>\n<h3 id=\"usefeed\" tabindex=\"-1\"><code>useFeed</code></h3>\n<p><em>Source:</em> <code>hooks/useFeed.ts</code></p>\n<p>Paginated combined feed of revisions from watchlist-style page and user lists via getCombinedFeed.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>{ wiki, pageSearchQueries, userSearchQueries, allRevisionsDataRef, }</code></li>\n</ul>\n<pre><code class=\"language-ts\">useFeed({\n\twiki,\n\tpageSearchQueries,\n\tuserSearchQueries,\n\tallRevisionsDataRef,\n}: UseFeedArgs)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import { ref } from &quot;vue&quot;\nimport { useFeed } from &quot;fakewiki&quot;\n// `wiki` is a FakeWiki instance\nconst pageSearchQueries = ref&lt;string[]&gt;([&quot;Cat&quot;])\nconst userSearchQueries = ref&lt;string[]&gt;([])\nconst { loadFeed, allRevisionsData } = useFeed({ wiki, pageSearchQueries, userSearchQueries })\nawait loadFeed()\n</code></pre>\n<p><em>Import:</em> <code>import { useFeed } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"uselistbuildingrecommendations\" tabindex=\"-1\"><code>useListBuildingRecommendations</code></h3>\n<p><em>Source:</em> <code>hooks/useListBuildingRecommendations.ts</code></p>\n<p>Watches the feed and enqueues list-building API recommendations, merging tagged revisions into <code>allRevisionsData</code>.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>{ wiki, pageSearchQueries, allRevisionsData, options: opts, }</code></li>\n</ul>\n<pre><code class=\"language-ts\">useListBuildingRecommendations({\n\twiki,\n\tpageSearchQueries,\n\tallRevisionsData,\n\toptions: opts,\n}: UseListBuildingRecommendationsArgs)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import { ref } from &quot;vue&quot;\nimport { useListBuildingRecommendations } from &quot;fakewiki&quot;\n// `wiki` is a FakeWiki instance\nconst pageSearchQueries = ref&lt;string[]&gt;([&quot;Cat&quot;])\nconst allRevisionsData = ref([])\nuseListBuildingRecommendations({ wiki, pageSearchQueries, allRevisionsData })\n</code></pre>\n<p><em>Import:</em> <code>import { useListBuildingRecommendations } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"usepredictions\" tabindex=\"-1\"><code>usePredictions</code></h3>\n<p><em>Source:</em> <code>hooks/usePredictions.ts</code></p>\n<p>Load and resolve damaging / goodfaith (and related) per-revision predictions from Lift Wing or ORES, with shared threshold and icon state.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>wiki</code> - <code>FakeWiki</code> instance</li>\n<li><code>options</code> - Model source, thresholds, optional debug mode</li>\n</ul>\n<pre><code class=\"language-ts\">usePredictions(wiki: FakeWiki, options?: UsePredictionsOptions)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const pred = usePredictions(wiki, { source: &quot;liftwing&quot;, models: [&quot;damaging&quot;, &quot;goodfaith&quot;] })\nconst prediction = pred.getPrediction(12345, &quot;damaging&quot;)\n</code></pre>\n<p><em>Import:</em> <code>import { usePredictions } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"userelatedchanges\" tabindex=\"-1\"><code>useRelatedChanges</code></h3>\n<p><em>Source:</em> <code>hooks/useRelatedChanges.ts</code></p>\n<p>Loads related changes for a single page (getRelatedChanges) or multiple seeds (getTopRelatedChanges) and normalizes comment HTML.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>{ wiki, pageName, options: opts, }</code></li>\n</ul>\n<pre><code class=\"language-ts\">useRelatedChanges({\n\twiki,\n\tpageName,\n\toptions: opts,\n}: UseRelatedChangesArgs)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import { ref } from &quot;vue&quot;\nimport { useRelatedChanges } from &quot;fakewiki&quot;\n// `wiki` is a FakeWiki instance\nconst pageName = ref(&quot;Cat&quot;)\nconst { loadFeed } = useRelatedChanges({ wiki, pageName, options: {} })\nawait loadFeed()\n</code></pre>\n<p><em>Import:</em> <code>import { useRelatedChanges } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"userelatedchangesrecommendations\" tabindex=\"-1\"><code>useRelatedChangesRecommendations</code></h3>\n<p><em>Source:</em> <code>hooks/useRelatedChangesRecommendations.ts</code></p>\n<p>Suggests extra pages from list-building, then loads top-related changes to flag feed rows as recommendations.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>{ wiki, pageSearchQueries, allRevisionsData, filterKeepPercent, options: opts, }</code></li>\n</ul>\n<pre><code class=\"language-ts\">useRelatedChangesRecommendations({\n\twiki,\n\tpageSearchQueries,\n\tallRevisionsData,\n\tfilterKeepPercent,\n\toptions: opts,\n}: UseRelatedChangesRecommendationsArgs)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import { ref } from &quot;vue&quot;\nimport { useRelatedChangesRecommendations } from &quot;fakewiki&quot;\n// `wiki` is a FakeWiki instance\nconst pageSearchQueries = ref&lt;string[]&gt;([&quot;Cat&quot;])\nconst allRevisionsData = ref([])\nconst filterKeepPercent = ref(15)\nuseRelatedChangesRecommendations({ wiki, pageSearchQueries, allRevisionsData, filterKeepPercent })\n</code></pre>\n<p><em>Import:</em> <code>import { useRelatedChangesRecommendations } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"usestructureddeltas\" tabindex=\"-1\"><code>useStructuredDeltas</code></h3>\n<p><em>Source:</em> <code>hooks/useStructuredDeltas.ts</code></p>\n<p>Fetches edit-types summaries and computes structured-delta candidates per revision, with user-tunable settings.</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>{ wiki, revisionIds, initialSettings, loadConcurrency: loadConcurrencyArg, autoLoad = true, initialEditTypesSummaries, initialEditTypesErrors, }</code></li>\n</ul>\n<pre><code class=\"language-ts\">useStructuredDeltas({\n\twiki,\n\trevisionIds,\n\tinitialSettings,\n\tloadConcurrency: loadConcurrencyArg,\n\tautoLoad = true,\n\tinitialEditTypesSummaries,\n\tinitialEditTypesErrors,\n}: UseStructuredDeltasArgs)\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">import { ref } from &quot;vue&quot;\nimport { useStructuredDeltas } from &quot;fakewiki&quot;\n// `wiki` is a FakeWiki instance\nconst revisionIds = ref([12345, 12346])\nconst deltas = useStructuredDeltas({ wiki, revisionIds, autoLoad: false })\ndeltas.loadEditTypesSummaries([12345, 12346])\n</code></pre>\n<p><em>Import:</em> <code>import { useStructuredDeltas } from &quot;fakewiki&quot;</code></p>\n<h3 id=\"useuser\" tabindex=\"-1\"><code>useUser</code></h3>\n<p><em>Source:</em> <code>hooks/useUser.ts</code></p>\n<p>Thin wrapper that returns getUserCategoryDisplay (async) and getCachedUserCategoryDisplay (sync) from the given FakeWiki instance.<br>\nIn templates where the feed has already loaded (and populated the user category cache), use getCachedUserCategoryDisplay for synchronous access.<br>\nUse getUserCategoryDisplay when you need to ensure the user is loaded (e.g. await in script).</p>\n<p><strong>Parameters (from JSDoc <code>@param</code> where present)</strong></p>\n<ul>\n<li><code>wiki</code> - <code>FakeWiki</code> instance</li>\n<li><code>options</code> - Optional <code>userTypeConfig</code> override map for display icons and colors</li>\n</ul>\n<pre><code class=\"language-ts\">useUser(wiki: FakeWiki,\n\toptions?: { userTypeConfig?: Partial&lt;Record&lt;FWUserCategory, FWUserTypeConfig&gt;&gt; })\n</code></pre>\n<p><strong>Example</strong></p>\n<pre><code class=\"language-ts\">const { getCachedUserCategoryDisplay, getUserCategoryDisplay } = useUser(wiki)\nconst display = getCachedUserCategoryDisplay(&quot;Example&quot;)\n</code></pre>\n<p><em>Import:</em> <code>import { useUser } from &quot;fakewiki&quot;</code></p>\n"
